INSERT INTO "knowledge"."route_version" (route_id, number, content, content_hash, cases) VALUES
  ('dk-pay-limit', 3, '{"schemaVersion":1,"routeId":"dk-pay-limit","number":3,"title":"Danish residence and work permit under the Pay Limit Scheme: a job offer with annual pay of at least DKK 552,000 (2026)","country":"DK","tags":["work","temporary-residence"],"effectiveFrom":"2026-01-01","status":"open","currency":"DKK","leapDayBirthday":"unsettled","sources":[{"id":"aliens-act-pay-limit","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act (consolidated Act No. 953 of 2026), § 9 a(2)(3) and (29): a job offer with annual pay of at least DKK 400,000, adjusted each year in line with wage growth and rounded to DKK 1,000","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"siri-pay-limit","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Work/Pay-limit-scheme","title":"SIRI, the Pay Limit Scheme: the pay limit is DKK 552,000 a year for 2026, set each 1 January; only cash pay, pension and paid holiday allowance count; pay and terms usual in Denmark","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-act-employment-terms","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, § 9 a(9), (10), (25) and (26): at least 30 hours a week; pay into a Danish bank account; no permit for a job in a lawful labour dispute or for an offer that is not genuine","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"aliens-act-social-assistance","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, § 9 a(4): the permit requires that the principal and the family members who get permits through them receive no assistance under the Active Social Policy Act","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"aliens-act-family","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, § 9 m(1): where essential business or employment interests favour it, a family member of a foreigner with a § 9 a(2) permit may get one, if they share a home","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"siri-accompanying-family","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Family/Accompanying-family-members/Accompanying-family---work","title":"SIRI, accompanying family of employees: a spouse or registered partner, a cohabiting partner over 18 after at least 1.5 to 2 years living together, and a child under 18","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-act-free-movement","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, §§ 1 and 2: citizens of Finland, Iceland, Norway and Sweden live in Denmark without a permit; EU and EEA citizens fall under the EU rules on free movement","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"eu-residence-order","url":"https://www.retsinformation.dk/eli/lta/2020/1457","title":"EU Residence Order (Order No. 1457 of 2020), §§ 1(2) and 2(2): Swiss citizens are treated like EU citizens under the EU rules on free movement","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2020/1457/xml"},{"id":"guardianship-act-minors","url":"https://www.retsinformation.dk/eli/lta/2021/1122","title":"Guardianship Act (consolidated Act No. 1122 of 2021), § 1(1): children and young people under 18 who have not married are minors","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2021/1122/xml"},{"id":"fee-order-principal","url":"https://www.retsinformation.dk/eli/lta/2025/1612","title":"Order No. 1612 of 2025 on fees, § 5(2)(1): for 1 January to 31 December 2026 the fee for a permit application under Aliens Act § 9 a(2)(1) to (9) and (11) to (14) is DKK 6,810","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2025/1612/xml"},{"id":"fee-order-family","url":"https://www.retsinformation.dk/eli/lta/2025/1612","title":"Order No. 1612 of 2025 on fees, § 5(5)(1): for 1 January to 31 December 2026 the fee for a permit application under Aliens Act § 9 m(1) and (2), for family members, is DKK 3,080","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2025/1612/xml"},{"id":"aliens-act-fee","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, § 9 h(1)(4) and (9) and (2): a fee is paid no later than with an application under § 9 a(2)(1) to (14) or § 9 m(1); the minister sets the fees","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"siri-processing-and-duration","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Work/Pay-limit-scheme","title":"SIRI, the Pay Limit Scheme: normal processing time 1 month, up to 3 months if more information is needed; a permit for the employment period, normally 4 years at most","kind":"official","verifiedAt":"2026-11-20"},{"id":"aliens-act-revocations","url":"https://www.retsinformation.dk/eli/lta/2026/953","title":"Aliens Act, § 9 a(4), second sentence: the permit requires that family members who get permits through the principal do not have their permit revoked more than once under § 19(1)(19)","kind":"official","verifiedAt":"2026-11-20","machineReadableUrl":"https://www.retsinformation.dk/eli/lta/2026/953/xml"},{"id":"siri-conditions","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Work/Pay-limit-scheme","title":"SIRI, the Pay Limit Scheme: some jobs need a Danish authorisation, or a temporary one, first; family members must not have had a permit revoked more than once for lack of a work permit","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-recognised-union","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Family/Accompanying-family-members/Accompanying-family---work","title":"SIRI, accompanying family: a marriage or registered partnership counts if legal where made, both present and 18 or more then, not one of convenience, not against fundamental legal principles","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-other-family","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Family/Accompanying-family-members/Accompanying-family---work","title":"SIRI, accompanying family of employees: other family members only where extraordinary circumstances and weighty considerations apply, such as long dependence on the sponsor","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-family-processing","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Family/Accompanying-family-members/Accompanying-family---work","title":"SIRI, accompanying family of employees: normal processing time 2 months, up to 3 months if more information is needed","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-danish-employer","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Work/Pay-limit-scheme","title":"SIRI, the Pay Limit Scheme: as a general rule an employment agreement with a company registered in Denmark, with exceptions such as a foreign company providing services in Denmark","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-custody-consent","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Family/Accompanying-family-members/Accompanying-family---work","title":"SIRI, accompanying family of employees: a child coming with one of two parents who share custody needs the other''s consent; sole custody must be documented","kind":"official","verifiedAt":"2026-11-20"},{"id":"siri-passport-validity","url":"https://www.nyidanmark.dk/en-GB/You-want-to-apply/Work/Pay-limit-scheme","title":"SIRI, the Pay Limit Scheme: a residence permit can only be valid until 3 months before the passport expires","kind":"official","verifiedAt":"2026-11-20"}],"countries":{"id":"countries","number":1},"formerCountries":{"id":"former-countries","number":1},"officialDomains":[{"id":"dk","number":1}],"countrySets":[{"id":"eu-free-movement","number":2}],"requirements":[{"id":"not-nordic-eu-eea-or-swiss-citizen","title":"Not a citizen of Denmark, another Nordic country, an EU or EEA state or Switzerland: they live and work in Denmark without this permit","expression":{"op":"not","operand":{"op":"intersects","list":{"op":"fact","key":"principal.citizenships"},"set":{"op":"set","id":"eu-free-movement"}}},"sources":["aliens-act-free-movement","eu-residence-order"]}],"assessments":[{"id":"pay-limit","title":"A job offer in Denmark with annual pay of at least the pay limit: DKK 400,000 in the act, adjusted each year for wage growth; DKK 552,000 for 2026 as SIRI publishes it","evidence":["principal.monthlyActiveIncome"],"sources":["aliens-act-pay-limit","siri-pay-limit"]},{"id":"working-hours","title":"Employment of at least 30 hours a week","evidence":["principal.monthlyActiveIncome"],"sources":["aliens-act-employment-terms","siri-pay-limit"]},{"id":"danish-bank-account","title":"Pay goes into a Danish bank account in the principal''s own name, opened within 180 days of entry or of the permit by someone who does not yet hold a permit of at least 180 days","evidence":["principal.monthlyActiveIncome"],"sources":["aliens-act-employment-terms","siri-pay-limit"]},{"id":"usual-terms","title":"Pay and employment terms not inferior to the Danish standards of the professional field","evidence":["principal.monthlyActiveIncome"],"sources":["siri-pay-limit"]},{"id":"genuine-offer","title":"No permit for a job in a lawful labour dispute, where the actual employment is presumed not to match the application nor meet the conditions, or where the offer mainly serves to obtain residence","evidence":["principal.monthlyActiveIncome"],"sources":["aliens-act-employment-terms"]},{"id":"no-social-assistance","title":"Neither the principal nor the family members with permits through them receive assistance under the Active Social Policy Act","evidence":["unit.liquidAssets"],"sources":["aliens-act-social-assistance"]},{"id":"shared-home","title":"Family members live at the same address as the principal and receive no assistance under the Active Social Policy Act","evidence":["unit.liquidAssets"],"sources":["aliens-act-family","siri-accompanying-family"]},{"id":"danish-authorisation","title":"Where the job needs a Danish authorisation, such as a doctor''s, the authorisation, or a temporary one for adaptation and training, held before the permit is granted","evidence":["principal.educationLevel"],"sources":["siri-conditions"]},{"id":"family-permits-not-revoked","title":"The permit is conditional on no family member with a permit through the principal having that permit revoked more than once for lack of a required work permit","evidence":["principal.hasSpouse"],"sources":["aliens-act-revocations","siri-conditions"]},{"id":"recognised-union","title":"A spouse''s marriage or registered partnership must be one Danish law recognises: legal where made, both present and 18 or more then, not of convenience, not against fundamental legal principles","evidence":["principal.hasSpouse"],"sources":["siri-recognised-union"]},{"id":"danish-employer","title":"As a general rule, the employment agreement is with a company registered in Denmark; exceptions exist, such as a foreign company providing services in Denmark","evidence":["principal.monthlyActiveIncome"],"sources":["siri-danish-employer"]},{"id":"custody-consent","title":"A child coming with only one of two parents who share custody needs the other parent''s consent; a parent with sole custody documents it","evidence":["principal.hasSpouse"],"sources":["siri-custody-consent"]}],"dependents":[{"id":"spouse","title":"Spouse who was 18 or more at the wedding; married younger, with both now 18 or more: possible, since SIRI then assesses the couple as cohabiting partners","path":["spouse"],"condition":{"op":"any","operands":[{"op":"gte","left":{"op":"fact","key":"edge.ageAtStart"},"right":{"op":"int","value":18}},{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"gte","left":{"op":"fact","key":"principal.ageYears"},"right":{"op":"int","value":18}},{"op":"unmodeled"}]}]},"sources":["aliens-act-family","siri-accompanying-family"]},{"id":"partner","title":"Cohabiting partner over 18: SIRI asks, as a rule, for at least 1.5 to 2 years living together, so 2 years or more counts, and 1.5 to 2 years, or a registered partnership, is possible","path":["partner"],"condition":{"op":"all","operands":[{"op":"gte","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"gte","left":{"op":"fact","key":"principal.ageYears"},"right":{"op":"int","value":18}},{"op":"any","operands":[{"op":"since","date":{"op":"fact","key":"edge.start"},"duration":"P2Y"},{"op":"unmodeled"}]}]},"sources":["aliens-act-family","siri-accompanying-family","guardianship-act-minors"]},{"id":"children","title":"Children under 18; an older child who depends on the principal: possible, only where SIRI finds extraordinary circumstances and weighty considerations","path":["child"],"condition":{"op":"any","operands":[{"op":"lt","left":{"op":"fact","key":"person.ageYears"},"right":{"op":"int","value":18}},{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]}]},"sources":["aliens-act-family","siri-accompanying-family","guardianship-act-minors","siri-other-family"]},{"id":"parents","title":"Parents who depend on the principal: possible, only where SIRI finds extraordinary circumstances and weighty considerations","path":["parent"],"condition":{"op":"all","operands":[{"op":"fact","key":"person.dependsOnPrincipal"},{"op":"unmodeled"}]},"sources":["aliens-act-family","siri-other-family"]}],"costs":[{"i